// C3 唯一字段表，原专业结果与 terms 字段直接用原 owner 的字段出口。
#pragma once
#include "professional_order_contract.hpp"
#include "resident/model/professional_outcome_codec.hpp"
#include "resident/model/commitment_ref_codec.hpp"
#include "resident/domains/services/service_actual_termination_codec_fields.hpp"
namespace hanmo::resident::professional_order_codec {
template<class A>Status criterion(A&a,ProfessionalCriterion&v){a.field("criterion_kind",v.criterion_kind);return a.field("criterion_version",v.criterion_version);}
template<class A>Status acceptance_key(A&a,OrderServiceAcceptanceKey&v){a.field("order_id",v.order_id);a.field("line_id",v.line_id);return a.object("first_accepted_terms_ref",[&](auto&c){return commitment_codec::terms(c,v.first_accepted_terms_ref);});}
template<class A>Status job(A&a,OrderedProfessionalJobRef&v){Integer tag=v.index();a.field("tag",tag);if(tag<0||tag>2)return a.reject("UnknownOrderedProfessionalJob");if(a.reading()){switch(tag){case 0:v=OrderedCopyJob{};break;case 1:v=OrderedInfusionJob{};break;case 2:v=OrderedArcaneJob{};break;}}
 if(tag==0)return a.object("copy_activity_ref",[&](auto&c){return service_termination_codec::source(c,std::get<OrderedCopyJob>(v).copy_activity_ref);});if(tag==1)return a.field("job_id",std::get<OrderedInfusionJob>(v).job_id);auto&x=std::get<OrderedArcaneJob>(v);a.field("service_id",x.service_id);Integer kind=static_cast<Integer>(x.kind);a.field("kind",kind);if(kind<0||kind>2)return a.reject("UnknownOrderedArcaneKind");if(a.reading())x.kind=static_cast<OrderedArcaneKind>(kind);return a.status();
}
template<class A>Status follow_through(A&a,OrderedFollowThroughRef&v){a.object("acceptance_key",[&](auto&c){return acceptance_key(c,v.acceptance_key);});a.field("obligation_ordinal",v.obligation_ordinal);return a.object("kind",[&](auto&c){Integer tag=v.kind.index();c.field("tag",tag);if(tag<0||tag>2)return c.reject("UnknownOrderedFollowThrough");if(c.reading()){switch(tag){case 0:v.kind=OrderedReturnCustomerInstance{};break;case 1:v.kind=OrderedDeliverProducedCopies{};break;case 2:v.kind=OrderedDeliverProfessionalResult{};break;}}
 if(tag==0){auto&x=std::get<OrderedReturnCustomerInstance>(v.kind);c.field("item_instance_id",x.item_instance_id);c.object("original_custody_terms_ref",[&](auto&n){return service_termination_codec::source(n,x.original_custody_terms_ref);});return c.object("recipient_terms_ref",[&](auto&n){return service_termination_codec::source(n,x.recipient_terms_ref);});}
 if(tag==1){auto&x=std::get<OrderedDeliverProducedCopies>(v.kind);c.object("copy_activity_ref",[&](auto&n){return service_termination_codec::source(n,x.copy_activity_ref);});c.field("required_output_count",x.required_output_count);return c.object("delivery_terms_ref",[&](auto&n){return service_termination_codec::source(n,x.delivery_terms_ref);});}
 auto&x=std::get<OrderedDeliverProfessionalResult>(v.kind);c.object("job",[&](auto&n){return job(n,x.job);});c.object("recipient_terms_ref",[&](auto&n){return service_termination_codec::source(n,x.recipient_terms_ref);});return c.object("disclosure_terms_ref",[&](auto&n){return service_termination_codec::source(n,x.disclosure_terms_ref);});
 });}
template<class A>Status binding(A&a,OrderedProfessionalBinding&v){a.object("acceptance_key",[&](auto&c){return acceptance_key(c,v.acceptance_key);});a.object("job",[&](auto&c){return job(c,v.job);});a.object("professional_terms_ref",[&](auto&c){return commitment_codec::terms(c,v.professional_terms_ref);});a.object("accepted_criterion",[&](auto&c){return criterion(c,v.accepted_criterion);});Integer fee=static_cast<Integer>(v.fee_rule);a.field("fee_rule",fee);if(fee!=0)return a.reject("UnknownOrderedCompletionFeeRule");if(a.reading())v.fee_rule=OrderedCompletionFeeRule::ordered_professional_completion_v1;a.object("fee_terms_ref",[&](auto&c){return service_termination_codec::source(c,v.fee_terms_ref);});a.sequence("accepted_follow_through",v.accepted_follow_through,[](auto&c,auto&r){return follow_through(c,r);});a.object("continuity_terms_ref",[&](auto&c){return service_termination_codec::source(c,v.continuity_terms_ref);});a.object("attempt_rule",[&](auto&c){Integer tag=v.attempt_rule.index();c.field("tag",tag);if(tag<0||tag>1)return c.reject("UnknownOrderedAttemptRule");if(c.reading())v.attempt_rule=tag==0?OrderedProfessionalAttemptRule{OrderedSingleCompleteExecution{}}:OrderedProfessionalAttemptRule{OrderedOriginalReworkClause{}};if(tag==0)return c.status();auto&x=std::get<OrderedOriginalReworkClause>(v.attempt_rule);c.object("terms_ref",[&](auto&n){return commitment_codec::terms(n,x.terms_ref);});return c.field("clause_ordinal",x.clause_ordinal);});if(!a.status().ok)return a.status();auto valid=validate_ordered_professional_binding_shape(v);return valid.ok?a.status():a.reject(valid.error.original.code);}
template<class A>Status member(A&a,OrderedProfessionalExecutionMember&v){a.object("acceptance_key",[&](auto&c){return acceptance_key(c,v.acceptance_key);});a.field("execution_ordinal",v.execution_ordinal);a.object("job",[&](auto&c){return job(c,v.job);});a.object("professional_terms_ref",[&](auto&c){return commitment_codec::terms(c,v.professional_terms_ref);});a.object("authority",[&](auto&c){Integer tag=v.authority.index();c.field("tag",tag);if(tag<0||tag>1)return c.reject("UnknownOrderedExecutionAuthority");if(c.reading())v.authority=tag==0?OrderedProfessionalExecutionAuthority{OrderedInitialAcceptance{}}:OrderedProfessionalExecutionAuthority{OrderedReworkAuthority{}};if(tag==0)return c.status();auto&x=std::get<OrderedReworkAuthority>(v.authority);c.object("terms_ref",[&](auto&n){return commitment_codec::terms(n,x.terms_ref);});c.field("clause_ordinal",x.clause_ordinal);return c.field("preceding_execution_ordinal",x.preceding_execution_ordinal);});if(!a.status().ok)return a.status();auto valid=validate_ordered_execution_member_shape(v);return valid.ok?a.status():a.reject(valid.error.original.code);}
template<class A>Status fee_terms(A&a,OrderedCompletionFeeTerms&v){a.object("acceptance_key",[&](auto&c){return acceptance_key(c,v.acceptance_key);});a.field("fee_item_ordinal",v.fee_item_ordinal);a.field("quoted_qian",v.quoted_qian);a.object("criterion",[&](auto&c){return criterion(c,v.criterion);});a.object("payment_terms_ref",[&](auto&c){return service_termination_codec::source(c,v.payment_terms_ref);});if(!a.status().ok)return a.status();auto valid=validate_ordered_completion_fee_terms_shape(v);return valid.ok?a.status():a.reject(valid.error.original.code);}
template<class A>Status charge(A&a,OrderedCompletionChargeSource&v){a.object("charge_key",[&](auto&c){c.object("acceptance_key",[&](auto&n){return acceptance_key(n,v.charge_key.acceptance_key);});return c.field("fee_item_ordinal",v.charge_key.fee_item_ordinal);});a.object("fee_terms_ref",[&](auto&c){return service_termination_codec::source(c,v.fee_terms_ref);});a.object("job",[&](auto&c){return job(c,v.job);});a.object("qualifying_outcome",[&](auto&c){return professional_codec::outcome_ref(c,v.qualifying_outcome);});a.object("criterion",[&](auto&c){return criterion(c,v.criterion);});a.field("earned_qian",v.earned_qian);a.field("earned_tick",v.earned_tick);if(!a.status().ok)return a.status();auto valid=validate_ordered_completion_charge_shape(v);return valid.ok?a.status():a.reject(valid.error.original.code);}
}
